import{f as t,o as a,c as r,a2 as l}from"./chunks/framework.n5RLHRfo.js";const f=JSON.parse('{"title":"Sprite & SpriteSheet","description":"","frontmatter":{"title":"Sprite & SpriteSheet","order":1},"headers":[],"relativePath":"ko/extended-objects/sprite/index.md","filePath":"ko/extended-objects/sprite/index.md","lastUpdated":1792993711000}'),i={name:"ko/extended-objects/sprite/index.md"};function s(n,e,o,d,p,h){return a(),r("div",null,[...e[0]||(e[0]=[l('<h1 id="스프라이트" tabindex="-1">스프라이트 <a class="header-anchor" href="#스프라이트" aria-label="Permalink to &quot;스프라이트&quot;">​</a></h1><p>RedGPU는 3D 공간에서 2D 이미지를 효과적으로 활용할 수 있는 <strong>Sprite</strong> 시스템을 제공합니다. 항상 카메라를 향하는 <strong>빌보드</strong>(Billboard) 기능과 프레임 애니메이션을 지원하는 스프라이트 시트 기능을 통해 씬에 생동감을 불어넣을 수 있습니다.</p><h2 id="_1-주요-특징" tabindex="-1">1. 주요 특징 <a class="header-anchor" href="#_1-주요-특징" aria-label="Permalink to &quot;1. 주요 특징&quot;">​</a></h2><ul><li><strong>빌보드</strong>(Billboard) 지원 : 3D 공간에 배치되지만 항상 카메라를 정면으로 바라보도록 설정할 수 있어 UI, 파티클, 아이콘 등에 최적화되어 있습니다.</li><li><strong>애니메이션 시스템</strong>: 하나의 텍스처에 여러 프레임이 포함된 시트를 사용하여 고성능 2D 애니메이션을 구현할 수 있습니다.</li><li><strong>자동 종횡비 조절</strong>: 텍스처의 크기에 맞춰 스프라이트의 렌더링 비율이 자동으로 조정됩니다.</li></ul><h2 id="_2-주요-구성-요소" tabindex="-1">2. 주요 구성 요소 <a class="header-anchor" href="#_2-주요-구성-요소" aria-label="Permalink to &quot;2. 주요 구성 요소&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">클래스명</th><th style="text-align:left;">설명</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><a href="/RedGPU/manual/ko/api/RedGPU-API/namespaces/RedGPU/namespaces/Display/classes/Sprite3D.html"><code>Sprite3D</code></a></strong></td><td style="text-align:left;">단일 이미지를 사용하는 3D 스프라이트 객체입니다.</td></tr><tr><td style="text-align:left;"><strong><a href="/RedGPU/manual/ko/api/RedGPU-API/namespaces/RedGPU/namespaces/Display/classes/SpriteSheet3D.html"><code>SpriteSheet3D</code></a></strong></td><td style="text-align:left;">프레임 애니메이션을 지원하는 스프라이트 시트 객체입니다.</td></tr><tr><td style="text-align:left;"><strong><a href="/RedGPU/manual/ko/api/RedGPU-API/namespaces/RedGPU/namespaces/Display/classes/SpriteSheetInfo.html"><code>SpriteSheetInfo</code></a></strong></td><td style="text-align:left;">스프라이트 시트의 구조(세그먼트, 프레임 수 등)를 정의하는 데이터 객체입니다.</td></tr></tbody></table><h2 id="학습-로드맵" tabindex="-1">학습 로드맵 <a class="header-anchor" href="#학습-로드맵" aria-label="Permalink to &quot;학습 로드맵&quot;">​</a></h2><ol><li><strong><a href="./sprite.html">Sprite3D</a></strong>: 단일 이미지를 이용한 빌보드 스프라이트 만들기</li><li><strong><a href="./spritesheet.html">SpriteSheet3D</a></strong>: 애니메이션이 포함된 스프라이트 시트 활용하기</li></ol><hr><h2 id="관련-예제" tabindex="-1">관련 예제 <a class="header-anchor" href="#관련-예제" aria-label="Permalink to &quot;관련 예제&quot;">​</a></h2><ul><li><a href="/RedGPU/examples/3d/sprite/sprite3D/" target="_blank" rel="noopener noreferrer">Sprite3D 기본</a></li><li><a href="/RedGPU/examples/3d/sprite/spriteSheet3D/" target="_blank" rel="noopener noreferrer">SpriteSheet3D 기본</a></li><li><a href="/RedGPU/examples/2d/sprite2D/basic/" target="_blank" rel="noopener noreferrer">Sprite2D 기본</a></li><li><a href="/RedGPU/examples/2d/spriteSheet2D/basic/" target="_blank" rel="noopener noreferrer">SpriteSheet2D 기본</a></li></ul><hr><p><a href="./sprite.html">다음 단계: Sprite3D 배우기</a></p>',13)])])}const S=t(i,[["render",s]]);export{f as __pageData,S as default};
